from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_OBS_KEYS = ("x", "y", "value", "quality")
_DIM_LIMITS = (
    ("width", 1, MAX_DIM, "bad width"),
    ("height", 1, MAX_DIM, "bad height"),
    ("cell_size", 1, None, "bad cell size"),
)


def accumulate_grid(raw: object) -> dict:
    error = _validate_input(raw)
    if error:
        return {"ok": False, "error": error}
    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        error = _validate_observation(obs)
        if error:
            return {"ok": False, "error": error}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue
        row = _to_index(obs["y"], height, cell_size, tolerance)
        col = _to_index(obs["x"], width, cell_size, tolerance)
        if row is None or col is None:
            dropped = dropped + 1
            continue
        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if not all(k in raw for k in ("grid", "observations", "fill_value")):
        return "missing field"
